static const NfcSupportedCardsPlugin* nfc_static_resolve(NfcStaticPluginEp ep) {
    const FlipperAppPluginDescriptor* d = ep();
    if(d == NULL) return NULL;
    if(strcmp(d->appid, NFC_SUPPORTED_CARD_PLUGIN_APP_ID) != 0) return NULL;
    if(d->ep_api_version != NFC_SUPPORTED_CARD_PLUGIN_API_VERSION) return NULL;
    return d->entry_point;
}

size_t nfc_supported_cards_static_count(void) {
    return COUNT_OF(nfc_static_parsers);
}

const NfcSupportedCardsPlugin* nfc_supported_cards_static_get_by_index(
    size_t index,
    const char** name_out) {
    if(index >= COUNT_OF(nfc_static_parsers)) return NULL;
    if(name_out) *name_out = nfc_static_parsers[index].name;
    return nfc_static_resolve(nfc_static_parsers[index].ep);
}

const NfcSupportedCardsPlugin* nfc_supported_cards_static_get_by_name(const char* name) {
    for(size_t i = 0; i < COUNT_OF(nfc_static_parsers); i++) {
        if(strcmp(nfc_static_parsers[i].name, name) == 0)
            return nfc_static_resolve(nfc_static_parsers[i].ep);
    }
    return NULL;
}
